            return ValueTask.FromResult(new ModuleResult(step.ErrorCode == 0 ? ModuleStatus.Success : ModuleStatus.Failed, outputs, step.ErrorCode == 0 ? null : "RotateCalibration", null) { NativeErrorCode = step.ErrorCode });
        }
    }
