		ImvsSdkDefine.IMVS_NODE_TREE_INFO? firstLayerModuleTree = ServerSDKManager.serverSDKManager.mProcessManager.GetFirstLayerModuleTree(ID, parentCode);
		LogHelper.Info("GetFirstLayerModuleTree获取后");
		VmModuleCollection<VmModule> vmModuleCollection = new VmModuleCollection<VmModule>();
		ImvsSdkDefine.IMVS_NODE_TREE_INFO? iMVS_NODE_TREE_INFO = firstLayerModuleTree;
		ImvsSdkDefine.IMVS_NODE_TREE_INFO valueOrDefault = iMVS_NODE_TREE_INFO.GetValueOrDefault();
		if (!iMVS_NODE_TREE_INFO.HasValue)
		{
			return;
		}
		for (int i = 0; i < valueOrDefault.nChildNodeNum; i++)
		{
			ImvsSdkDefine.IMVS_MODULE_INFO proInfo = valueOrDefault.astChildNodeInfo[i];
			try
			{
				bool flag = _preGenerateModules.ContainsKey(proInfo.nNodeID);
				VmModule vmModule = (flag ? _preGenerateModules[proInfo.nNodeID] : CreatModuleByInfo(proInfo));
				if (!flag)
				{
					vmModule.PreAddModuleTo(this);
				}
				vmModuleCollection.Add(vmModule);
			}
			catch (Exception ex)
			{
				string text = proInfo.nNodeID + " " + Hik.Util.StringUtil.UTF8GetString(proInfo.strDisplayName) + ", " + ex.Message;
				text = text + "\r\n" + ex.StackTrace;
				LogHelper.Error("Create module error: " + text);
